object","additionalProperties":false,"required":["discloses","actsAsSubject"],"properties":{"discloses":{"type":"string","enum":["none","metadata","secret"]},"actsAsSubject":{"type":"boolean"}},"description":"Authoritative exposure class (SPEC §7.3 item 14), likewise derived from the compiled handler. `discloses` is the sensitivity of returned data; `actsAsSubject` is whether the subject\'s authority is exercised."}}},"site":{"\$ref":"#/\$defs/SiteTarget"},"contextId":{"type":"string","minLength":1},"consumer":{"type":"object","additionalProperties":false,"required":["did"],"properties":{"did":{"type":"string"},"kind":{"\$ref":"#/\$defs/ConsumerKind"},"deviceId":{"type":"string"},"lastUserVerificationAt":{"type":"string","format":"date-time"},"networkClass":{"type":"string","enum":["unknown","home","corp","public","vpn"]}}}}},"ConsumerKind":{"title":"ConsumerKind","description":"Discriminator: is this consumer a user-driven Companion or a headless Service?","oneOf":[{"title":"Companion","type":"object","additionalProperties":false,"required":["kind","formFactor"],"properties":{"kind":{"const":"companion"},"formFactor":{"type":"string","enum":["browser","mobile","desktop"]}}},{"title":"Service","type":"object","additionalProperties":false,"required":["kind","serviceKind"],"properties":{"kind":{"const":"service"},"serviceKind":{"type":"string","enum":["mediator","aiAgent","daemon"]}}}]},"SiteTarget":{"title":"SiteTarget","description":"A single binding target for a vault entry. Tagged union over the discriminator `kind`. A VaultEntry\'s `targets` array MAY mix any number of these.","oneOf":[{"title":"WebOrigin","type":"object","additionalProperties":false,"required":["kind","origin"],"properties":{"kind":{"const":"webOrigin"},"origin":{"type":"string","format":"uri","description":"Web origin per RFC 6454 (scheme + host + optional port), e.g. \\"https://github.com\\". Compared by exact string equality after canonicalisation (lowercase host, default port elided). Consumers wanting subdomain coverage SHOULD add multiple targets, not encode a wildcard."}}},{"title":"Did","type":"object","additionalProperties":false,"required":["kind","did"],"properties":{"kind":{"const":"did"},"did":{"type":"string","minLength":1,"description":"DID identifying the relying party (e.g. did:web:rp.example). The vault maintainer is responsible for any DID resolution required to act on this entry."}}},{"title":"IosApp","type":"object","additionalProperties":false,"required":["kind","bundleId"],"properties":{"kind":{"const":"iosApp"},"bundleId":{"type":"string","minLength":1,"pattern":"^[A-Za-z0-9.-]+\$","description":"iOS bundle identifier in reverse-DNS form (e.g. \\"com.github.stwalkerster.codehub\\"). Compared by exact string equality. Matches when an iOS Companion identifies the requesting app via its bundle id (typically via the OS Credential Manager integration)."},"teamId":{"type":"string","minLength":1,"pattern":"^[A-Z0-9]+\$","description":"Optional Apple Developer Team identifier (10-character alphanumeric). When supplied, the maintainer SHOULD also verify the team id of the requesting app before matching — defense in depth against bundle-id squatting on jailbroken devices."}}},{"title":"AndroidApp","type":"object","additionalProperties":false,"required":["kind","packageName","sha256CertFingerprints"],"properties":{"kind":{"const":"androidApp"},"packageName":{"type":"string","minLength":1,"pattern":"^[A-Za-z][A-Za-z0-9_]*(\\\\.[A-Za-z][A-Za-z0-9_]*)+\$","description":"Android package name in reverse-DNS form (e.g. \\"com.github.android\\")."},"sha256CertFingerprints":{"type":"array","minItems":1,"items":{"type":"string","pattern":"^[0-9A-F]{2}(:[0-9A-F]{2}){31}\$"},"uniqueItems":true,"description":"SHA-256 fingerprints of the app\'s signing certificates, in colon-separated hex (the format `apksigner` and the Play Console emit). At least one fingerprint MUST be present. The maintainer matches when ANY of the provided fingerprints matches the requesting app\'s signature — this supports apps signed by multiple keys (e.g. during certificate rotation via Play App Signing)."}}}]},"DigestMultibase":{"title":"DigestMultibase","description":"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\"interoperability is not guaranteed between implementations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]}}